WITH filtered AS (SELECT id, promo_code, starts_on, FLOOR(discount_pct) AS discount_pct_whole, ROUND(discount_pct, 0) AS discount_pct_rounded FROM promotions WHERE ends_on > DATE '2023-09-15' AND channel IS NOT NULL) SELECT CASE WHEN discount_pct_whole >= 61 THEN 'LARGE' ELSE 'SMALL' END AS discount_pct_whole_tier, DATE_TRUNC('MONTH', starts_on) AS activity_month, COUNT(*) AS event_count, COUNT(DISTINCT promo_code) AS distinct_promo_codes, COUNT(DISTINCT id) AS distinct_ids FROM filtered GROUP BY CUBE (CASE WHEN discount_pct_whole >= 61 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('MONTH', starts_on)) HAVING distinct_promo_codes >= 1 ORDER BY activity_month ASC;
